// A module-level registry that refuses an id it already holds.
const ids = new Map()
class Entry {
  constructor(id) {
    this.id = id
  }
}
exports.Entry = Entry
exports.register = (id, entry) => {
  if (ids.has(id)) throw new RangeError('Duplicate use of entry id ' + id)
  ids.set(id, entry)
  return entry
}
exports.lookup = (id) => ids.get(id)

