// Registers an entry while it loads, through the barrel, and reads the DOM through dom-reader.
const registry = require('entry-registry-barrel')
const domReader = require('dom-reader')
const core = require('core-lib')
class PluginEntry extends registry.Entry {}
exports.entry = registry.register('plugin', new PluginEntry('plugin'))
exports.agent = domReader.agent
exports.core = core
